```
package org.example;

import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;

public class TetrisGame extends JFrame {
    private static final int BOARD_WIDTH = 10;
    private static final int BOARD_HEIGHT = 20;
    private static final int BLOCK_SIZE = 30;

    private Timer timer;
    private boolean isFallingFinished = false;
    private boolean isStarted = false;
    private boolean isPaused = false;
    private int numLinesRemoved = 0;
    private int curX = 0;
    private int curY = 0;

    private JLabel statusbar;
    private Shape curPiece;
    private Tetrominoes[] board;

    public TetrisGame() {
        initUI();
    }

    private void initUI() {
        statusbar = new JLabel(" 0");
        add(statusbar, BorderLayout.SOUTH);

        Board board = new Board(this);
        add(board);
        board.start();

        setTitle("俄罗斯方块");
        setSize(BOARD_WIDTH * BLOCK_SIZE + 15, 
               (BOARD_HEIGHT + 1) * BLOCK_SIZE + 40);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLocationRelativeTo(null);
    }

    public static void main(String[] args) {
        EventQueue.invokeLater(() -> {
            TetrisGame game = new TetrisGame();
            game.setVisible(true);
        });
    }

    class Board extends JPanel implements KeyListener {
        private TetrisGame parent;
        private int squareWidth() { return (int) getSize().getWidth() / BOARD_WIDTH; }
        private int squareHeight() { return (int) getSize().getHeight() / BOARD_HEIGHT; }

        public Board(TetrisGame parent) {
            this.parent = parent;
            setFocusable(true);
            addKeyListener(this);
        }

        void start() {
            curPiece = new Shape();
            board = new Tetrominoes[BOARD_WIDTH * BOARD_HEIGHT];
            clearBoard();
            newPiece();
            timer = new Timer(400, new GameCycle());
            isStarted = true;
            timer.start();
        }

        @Override
        public void paintComponent(Graphics g) {
            super.paintComponent(g);
            drawBoard(g);
            if (isStarted) {
                drawPiece(g, curPiece, curX, curY);
            }
        }

        private void drawBoard(Graphics g) {
            Dimension size = getSize();
            int boardTop = (int) size.getHeight() - BOARD_HEIGHT * squareHeight();

            for (int i = 0; i < BOARD_HEIGHT; i++) {
                for (int j = 0; j < BOARD_WIDTH; j++) {
                    Tetrominoes shape = shapeAt(j, BOARD_HEIGHT - i - 1);
                    if (shape != Tetrominoes.NoShape) {
                        drawSquare(g, j * squareWidth(), 
                                 boardTop + i * squareHeight(), shape);
                    }
                }
            }
        }

        private void drawPiece(Graphics g, Shape piece, int x, int y) {
            for (int i = 0; i < 4; i++) {
                int px = x + piece.x(i);
                int py = y - piece.y(i);
                drawSquare(g, px * squareWidth(), 
                         getSize().height - (py + 1) * squareHeight(), 
                         piece.getShape());
            }
        }

        private void drawSquare(Graphics g, int x, int y, Tetrominoes shape) {
            Color colors[] = { 
                new Color(0, 0, 0), new Color(204, 102, 102), 
                new Color(102, 204, 102), new Color(102, 102, 204),
                new Color(204, 204, 102), new Color(204, 102, 204), 
                new Color(102, 204, 204), new Color(218, 170, 0)
            };

            Color color = colors[shape.ordinal()];
            g.setColor(color);
            g.fillRect(x + 1, y + 1, squareWidth() - 2, squareHeight() - 2);

            g.setColor(color.brighter());
            g.drawLine(x, y + squareHeight() - 1, x, y);
            g.drawLine(x, y, x + squareWidth() - 1, y);

            g.setColor(color.darker());
            g.drawLine(x + 1, y + squareHeight() - 1,
                     x + squareWidth() - 1, y + squareHeight() - 1);
            g.drawLine(x + squareWidth() - 1, y + squareHeight() - 1,
                     x + squareWidth() - 1, y + 1);
        }

        @Override
        public void keyTyped(KeyEvent e) {

        }

        @Override
        public void keyPressed(KeyEvent e) {
            if (!isStarted || curPiece.getShape() == Tetrominoes.NoShape) {
                return;
            }

            int keycode = e.getKeyCode();

            if (keycode == 'p' || keycode == 'P') {
                pause();
                return;
            }

            if (isPaused) {
                return;
            }

            switch (keycode) {
                case KeyEvent.VK_LEFT:
                    tryMove(curPiece, curX - 1, curY);
                    break;
                case KeyEvent.VK_RIGHT:
                    tryMove(curPiece, curX + 1, curY);
                    break;
                case KeyEvent.VK_DOWN:
                    oneLineDown();
                    break;
                case KeyEvent.VK_UP:
                    tryMove(curPiece.rotateRight(), curX, curY);
                    break;
                case KeyEvent.VK_SPACE:
                    dropDown();
                    break;
                case 'd':
                case 'D':
                    oneLineDown();
                    break;
            }
        }

        @Override
        public void keyReleased(KeyEvent e) {

        }

        private void dropDown() {
            int newY = curY;
            while (newY > 0) {
                if (!tryMove(curPiece, curX, newY - 1)) {
                    break;
                }
                newY--;
            }
            pieceDropped();
        }

        private void oneLineDown() {
            if (!tryMove(curPiece, curX, curY - 1)) {
                pieceDropped();
            }
        }

        private void pieceDropped() {
            for (int i = 0; i < 4; i++) {
                int x = curX + curPiece.x(i);
                int y = curY - curPiece.y(i);
                board[y * BOARD_WIDTH + x] = curPiece.getShape();
            }

            removeFullLines();

            if (!isFallingFinished) {
                newPiece();
            }
        }

        private void removeFullLines() {
            int numFullLines = 0;

            for (int i = BOARD_HEIGHT - 1; i >= 0; i--) {
                boolean lineIsFull = true;

                for (int j = 0; j < BOARD_WIDTH; j++) {
                    if (shapeAt(j, i) == Tetrominoes.NoShape) {
                        lineIsFull = false;
                        break;
                    }
                }

                if (lineIsFull) {
                    numFullLines++;
                    for (int k = i; k < BOARD_HEIGHT - 1; k++) {
                        for (int j = 0; j < BOARD_WIDTH; j++) {
                            board[k * BOARD_WIDTH + j] = shapeAt(j, k + 1);
                        }
                    }
                }
            }

            if (numFullLines > 0) {
                numLinesRemoved += numFullLines;
                statusbar.setText(String.valueOf(numLinesRemoved));
                isFallingFinished = true;
                curPiece.setShape(Tetrominoes.NoShape);
                repaint();
            }
        }

        private void clearBoard() {
            for (int i = 0; i < BOARD_HEIGHT * BOARD_WIDTH; i++) {
                board[i] = Tetrominoes.NoShape;
            }
        }

        private void newPiece() {
            curPiece.setRandomShape();
            curX = BOARD_WIDTH / 2 - 1;
            curY = BOARD_HEIGHT - 1 + curPiece.minY();

            if (!tryMove(curPiece, curX, curY)) {
                curPiece.setShape(Tetrominoes.NoShape);
                timer.stop();
                isStarted = false;
                statusbar.setText("游戏结束! 得分: " + numLinesRemoved);
            }
        }

        private boolean tryMove(Shape newPiece, int newX, int newY) {
            for (int i = 0; i < 4; i++) {
                int x = newX + newPiece.x(i);
                int y = newY - newPiece.y(i);
                if (x < 0 || x >= BOARD_WIDTH || y < 0 || y >= BOARD_HEIGHT) {
                    return false;
                }
                if (shapeAt(x, y) != Tetrominoes.NoShape) {
                    return false;
                }
            }

            curPiece = newPiece;
            curX = newX;
            curY = newY;
            repaint();
            return true;
        }

        private Tetrominoes shapeAt(int x, int y) {
            return board[y * BOARD_WIDTH + x];
        }

        private void pause() {
            if (!isStarted) {
                return;
            }

            isPaused = !isPaused;
            if (isPaused) {
                timer.stop();
                statusbar.setText("游戏暂停");
            } else {
                timer.start();
                statusbar.setText(String.valueOf(numLinesRemoved));
            }
            repaint();
        }

        class GameCycle implements ActionListener {
            @Override
            public void actionPerformed(ActionEvent e) {
                if (isFallingFinished) {
                    isFallingFinished = false;
                    newPiece();
                } else {
                    oneLineDown();
                }
            }
        }
    }

    enum Tetrominoes {
        NoShape(new int[][] { {0, 0}, {0, 0}, {0, 0}, {0, 0} }),
        ZShape(new int[][] { {0, -1}, {0, 0}, {-1, 0}, {-1, 1} }),
        SShape(new int[][] { {0, -1}, {0, 0}, {1, 0}, {1, 1} }),
        LineShape(new int[][] { {0, -1}, {0, 0}, {0, 1}, {0, 2} }),
        TShape(new int[][] { {-1, 0}, {0, 0}, {1, 0}, {0, 1} }),
        SquareShape(new int[][] { {0, 0}, {1, 0}, {0, 1}, {1, 1} }),
        LShape(new int[][] { {-1, -1}, {0, -1}, {0, 0}, {0, 1} }),
        MirroredLShape(new int[][] { {1, -1}, {0, -1}, {0, 0}, {0, 1} });

        private int[][] coords;

        Tetrominoes(int[][] coords) {
            this.coords = coords;
        }
    }

    static class Shape {
        private int[][] coords;
        private Tetrominoes pieceShape;

        public Shape() {
            coords = new int[4][2];
            setShape(Tetrominoes.NoShape);
        }

        private void setX(int index, int x) { coords[index][0] = x; }
        private void setY(int index, int y) { coords[index][1] = y; }
        public int x(int index) { return coords[index][0]; }
        public int y(int index) { return coords[index][1]; }
        public Shape rotateLeft() {
            if (pieceShape == Tetrominoes.SquareShape) {
                return this;
            }

            Shape result = new Shape();
            result.pieceShape = pieceShape;

            for (int i = 0; i < 4; i++) {
                result.setX(i, -y(i));
                result.setY(i, x(i));
            }
            return result;
        }

        public Shape rotateRight() {
            if (pieceShape == Tetrominoes.SquareShape) {
                return this;
            }

            Shape result = new Shape();
            result.pieceShape = pieceShape;

            for (int i = 0; i < 4; i++) {
                result.setX(i, y(i));
                result.setY(i, -x(i));
            }
            return result;
        }

        public void setRandomShape() {
            var values = Tetrominoes.values();
            setShape(values[(int)(Math.random() * (values.length - 1)) + 1]);
        }

        public int minY() {
            int m = coords[0][1];
            for (int i = 0; i < 4; i++) {
                m = Math.min(m, coords[i][1]);
            }
            return m;
        }

        public void setShape(Tetrominoes shape) {
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 2; j++) {
                    coords[i][j] = shape.coords[i][j];
                }
            }
            pieceShape = shape;
        }

        public Tetrominoes getShape() {
            return pieceShape;
        }
    }
}

