    LNode *result_out = get_elem_by_index(head, index);
    if (result_out != NULL) {
        printf("索引 %d 的元素值: %d\n", index, result_out->data);
    } else {
        printf("索引 %d 索引无效或越界\n", index);
    }
    // 释放内存
    list_destroy(head);
    return TRUE;
}
```
