``` language
int delete_by_elem_value(LinkList head, LNode **tail, ElemType data) {
    if (NULL == head) {
        printf("[%s %d] head pointer is NULL ...\n", __FUNCTION__ , __LINE__);
        return FALSE;
    }
    LNode *t = head->next;
    LNode *p = head;
    //遍历到链表的末尾
    while (t != NULL) {
        //如果遍历到了需要删除的结点
        if (t->data == data) {
            //如果当前结点为尾结点
            if (t->next == NULL) {
                *tail = p;
                (*tail)->next = NULL;
                free(t);
                return TRUE;
            }
            //如果是中间的结点  前驱结点指向当前结点的下一个结点
            p->next = t->next;
            free(t);
            t = p->next;
        }
        else
        {
            t = t->next;
            p = p->next;
        }
    }
    return TRUE;
}
```
