``` language
void display_contacts(LinkList head) {
    if (head == NULL || head->next == NULL) {
        printf("通讯录为空！\n");
        return;
    }

    printf("\n%-20s %-15s %-30s\n", "姓名", "电话", "地址");
    printf("------------------------------------------------------------\n");

    LNode *current = head->next;
    while (current != NULL) {
        printf("%-20s %-15s %-30s\n", 
               current->data.name,
               current->data.phone,
               current->data.address);
        current = current->next;
    }
    printf("\n");
}
