**2）堆排序 (Heap Sort)**:
堆排序是一种高效的比较类排序算法，时间复杂度为O(n log n)，并且具有原地排序（空间复杂度O(1)）的优点。下面我将实现一个完整的堆排序程序。
关键函数：heapify。

```
void heapify(vector<int>& arr, int n, int i) {
    int largest = i;        // 初始化最大元素为根节点
    int left = 2 * i + 1;   // 左子节点
    int right = 2 * i + 2;  // 右子节点

    // 比较左子节点
    if (left < n && arr[left] > arr[largest])
        largest = left;

    // 比较右子节点
    if (right < n && arr[right] > arr[largest])
        largest = right;

    // 如果最大值不是根节点
    if (largest != i) {
        swap(arr[i], arr[largest]);  // 交换
        heapify(arr, n, largest);    // 递归调整子树
    }
}

```
完整代码如下：

```
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// 堆调整函数（大顶堆）
void heapify(vector<int>& arr, int n, int i) {
    int largest = i;        // 初始化最大元素为根节点
    int left = 2 * i + 1;   // 左子节点
    int right = 2 * i + 2;  // 右子节点

    // 如果左子节点存在且大于根节点
    if (left < n && arr[left] > arr[largest])
        largest = left;

    // 如果右子节点存在且大于当前最大值
    if (right < n && arr[right] > arr[largest])
        largest = right;

    // 如果最大值不是根节点
    if (largest != i) {
        swap(arr[i], arr[largest]);  // 交换
        heapify(arr, n, largest);    // 递归调整子树
    }
}

// 堆排序主函数
void heapSort(vector<int>& arr) {
    int n = arr.size();

    // 1. 构建大顶堆（从最后一个非叶子节点开始）
    for (int i = n / 2 - 1; i >= 0; i--)
        heapify(arr, n, i);

    // 2. 逐个提取元素（交换堆顶和末尾元素，然后调整堆）
    for (int i = n - 1; i > 0; i--) {
        swap(arr[0], arr[i]);  // 将当前最大值移到数组末尾
        heapify(arr, i, 0);    // 调整剩余元素组成的堆
    }
}

// 打印数组
void printArray(const vector<int>& arr) {
    for (int num : arr)
        cout << num << " ";
    cout << endl;
}

int main() {
    vector<int> arr = {12, 11, 13, 5, 6, 7, 20, 1, 8};

    cout << "排序前数组: ";
    printArray(arr);

    heapSort(arr);

    cout << "堆排序后数组: ";
    printArray(arr);

    // 测试不同情况
    vector<int> empty = {};
    vector<int> single = {5};
    vector<int> sorted = {1, 2, 3, 4, 5};
    vector<int> reverse = {9, 8, 7, 6, 5};
    vector<int> duplicates = {3, 1, 4, 1, 5, 9, 2, 6, 5};

    cout << "\n测试空数组: ";
    heapSort(empty);
    printArray(empty);

    cout << "测试单元素数组: ";
    heapSort(single);
    printArray(single);

    cout << "测试已排序数组: ";
    heapSort(sorted);
    printArray(sorted);

    cout << "测试逆序数组: ";
    heapSort(reverse);
    printArray(reverse);

    cout << "测试重复元素数组: ";
    heapSort(duplicates);
    printArray(duplicates);

    return 0;
}
