**3）删除堆顶元素 (DeleteMax / DeleteMin / Poll)**:

- 移除根节点元素（即数组的第一个元素）。
- 将数组的最后一个元素（最后一个叶子节点）移动到根节点位置。
- **下沉 (Percolate Down / Sift Down / Heapify / Sink)**: 比较新的根节点与其较大的（最大堆）或较小的（最小堆）子节点的值。
- 重复下沉，直到该节点找到合适的位置（满足堆序性），或者到达叶子节点。
- 时间复杂度：O(log n) (树的高度)。

删除代码样例如下，代码中添加了详细的输出信息，帮助理解求解过程：

```
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

class MinHeap {
private:
    vector<int> heap;

    // 获取父节点索引
    int parent(int i) { return (i - 1) / 2; }

    // 获取左子节点索引
    int leftChild(int i) { return 2 * i + 1; }

    // 获取右子节点索引
    int rightChild(int i) { return 2 * i + 2; }

    // 从指定位置开始向下调整堆
    void heapifyDown(int i) {
        int smallest = i;          // 初始化最小值位置
        int left = leftChild(i);    // 左子节点索引
        int right = rightChild(i);  // 右子节点索引
        int size = heap.size();

        // 与左子节点比较
        if (left < size && heap[left] < heap[smallest])
            smallest = left;

        // 与右子节点比较
        if (right < size && heap[right] < heap[smallest])
            smallest = right;

        // 如果最小值不是当前节点，则交换并递归调整
        if (smallest != i) {
            swap(heap[i], heap[smallest]);
            heapifyDown(smallest);  // 递归调整子树
        }
    }

public:
    // 删除堆顶元素
    void deleteTop() {
        if (heap.empty()) {
            cerr << "Heap is empty!" << endl;
            return;
        }

        // 将最后一个元素移到堆顶
        heap[0] = heap.back();
        heap.pop_back();

        // 从根节点开始向下调整
        heapifyDown(0);
    }

    // 插入元素
    void insert(int value) {
        heap.push_back(value);  // 添加到末尾
        int i = heap.size() - 1;

        // 向上调整
        while (i != 0 && heap[i] < heap[parent(i)]) {
            swap(heap[i], heap[parent(i)]);
            i = parent(i);
        }
    }

    // 获取堆顶元素
    int getTop() {
        if (heap.empty()) {
            cerr << "Heap is empty!" << endl;
            return -1; // 返回错误值
        }
        return heap[0];
    }

    // 打印堆
    void printHeap() {
        for (int val : heap)
            cout << val << " ";
        cout << endl;
    }
};

int main() {
    MinHeap heap;

    // 构建堆 [5, 3, 8, 1, 2]
    heap.insert(5);
    heap.insert(3);
    heap.insert(8);
    heap.insert(1);
    heap.insert(2);

    cout << "初始堆: ";
    heap.printHeap();  // 输出: 1 2 8 5 3（实际结构可能不同）

    // 删除堆顶
    heap.deleteTop();
    cout << "删除堆顶后: ";
    heap.printHeap();  // 输出: 2 3 8 5（堆结构）

    // 再删除一次
    heap.deleteTop();
    cout << "再删除堆顶后: ";
    heap.printHeap();  // 输出: 3 5 8（堆结构）

    return 0;
}

