### 3.2 一维数组操作

在C语言中，**一维数组**是一种基础数据结构，用于在连续内存空间中存储相同类型的多个元素。对一维数组的操作包括数组的最大值、数组最小值、数组平均值、数组反转和数组排序等。

具体代码操作如下：

Step1：复制以下代码，替换main.cpp文件中的代码。
```
#include <iostream>
using namespace std;

// 函数声明
void printArray(int arr[], int size);
void reverseArray(int arr[], int size);
int findMax(int arr[], int size);
int findMin(int arr[], int size);
float calculateAverage(int arr[], int size);
void bubbleSort(int arr[], int size);

int main() {
    int arr[] = {8, 3, 6, 2, 9, 1, 4, 7, 5};
    int size = sizeof(arr)/sizeof(arr[0]);

    printf("原始数组：");
    printArray(arr, size);

    printf("数组反转：");
    reverseArray(arr, size);
    printArray(arr, size);

    printf("最大值：%d\n", findMax(arr, size));
    printf("最小值：%d\n", findMin(arr, size));
    printf("平均值：%.2f\n", calculateAverage(arr, size));

    printf("排序后：");
    bubbleSort(arr, size);
    printArray(arr, size);
return 0;
}

// 打印数组
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// 反转数组
void reverseArray(int arr[], int size) {
    for (int i = 0; i < size/2; i++) {
        int temp = arr[i];
        arr[i] = arr[size-1-i];
        arr[size-1-i] = temp;
    }
}

// 查找最大值
int findMax(int arr[], int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// 查找最小值
int findMin(int arr[], int size) {
    int min = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

// 计算平均值
float calculateAverage(int arr[], int size) {
    int sum = 0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    return (float)sum / size;
}

// 冒泡排序
void bubbleSort(int arr[], int size) {
    for (int i = 0; i < size-1; i++) {
        for (int j = 0; j < size-i-1; j++) {
            if (arr[j] > arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}
```

