#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int main() {

    // 定义字符串
    // 自动计算长度(12字节：11字符+1'\0')
    char s1[] = "Hello World"; 
    printf("字符串s1: %s\n", s1);

    // 字符串长度
    int len = strlen("Hello"); 
    printf("字符串s1的长度: %d\n", len);   

    // 字符串的复制
    char source[] = "Hello C"; 
    char dest[20];
    // 安全复制
    strncpy(dest, source, sizeof(dest) - 1); 
    // 确保终止
    dest[sizeof(dest) - 1] = '\0'; 
    printf("复制字符串dest: %s\n", dest);

    // 字符串连接
    char str[50] = "你好，";
    // 安全连接
    strncat(str, "C语言!", sizeof(str) - strlen(str) - 1); 
    printf("复制字符串str: %s\n", str);

