## 4 综合案例：学生成绩管理系统

### 4.1 功能需求分析

学生成绩管理系统设计功能如下：

1.  打印出所有学生的考试成绩；
2.  计算出全班学生的平均分和最高分；
3.  所有学生的平均分按照降序排列；
4.  统计学生成绩分布情况（优秀、良好、中等、及格、不及格）。

### 4.2 代码实现及验证

Step1：复制以下代码，替换main.cpp文件中的代码。
```
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// 函数声明
void studentManagementSystem();

int main() {
    printf("\n=== 综合案例：学生成绩管理系统 ===\n");
    studentManagementSystem();
    return 0;
}

// 综合案例：学生成绩管理系统
void studentManagementSystem() {
    #define MAX_STUDENTS 100
    #define MAX_NAME_LENGTH 50

    typedef struct {
        int id;
        char name[MAX_NAME_LENGTH];
        float scores[3]; // 三门课程的成绩
        float average;
    } Student;

    Student students[MAX_STUDENTS];
    int count = 0;

    printf("\n--- 学生成绩管理系统 ---\n");

    // 添加学生数据
    students[count++] = (Student){1, "张三", {85, 90, 78}};
    students[count++] = (Student){2, "李四", {92, 88, 95}};
    students[count++] = (Student){3, "王五", {76, 85, 80}};

    // 计算平均分
    for (int i = 0; i < count; i++) {
        float sum = 0;
        for (int j = 0; j < 3; j++) {
            sum += students[i].scores[j];
        }
        students[i].average = sum / 3.0;
    }

    // 打印学生成绩
    printf("\n%-5s %-10s %-8s %-8s %-8s %-8s\n", 
           "ID", "姓名", "成绩1", "成绩2", "成绩3", "平均分");
    printf("------------------------------------------------\n");

    for (int i = 0; i < count; i++) {
        printf("%-5d %-10s %-8.1f %-8.1f %-8.1f %-8.1f\n",
               students[i].id,
               students[i].name,
               students[i].scores[0],
               students[i].scores[1],
               students[i].scores[2],
               students[i].average);
    }

    // 查找最高分学生
    int maxIndex = 0;
    for (int i = 1; i < count; i++) {
        if (students[i].average > students[maxIndex].average) {
            maxIndex = i;
        }
    }

    printf("\n最高分学生: %s (平均分: %.1f)\n", 
           students[maxIndex].name, students[maxIndex].average);

    // 按平均分排序
    for (int i = 0; i < count-1; i++) {
        for (int j = 0; j < count-i-1; j++) {
            if (students[j].average < students[j+1].average) {
                Student temp = students[j];
                students[j] = students[j+1];
                students[j+1] = temp;
            }
        }
    }

    // 打印排序结果
    printf("\n按平均分降序排列:\n");
    printf("%-5s %-10s %-8s\n", "ID", "姓名", "平均分");
    printf("-----------------------\n");
    for (int i = 0; i < count; i++) {
        printf("%-5d %-10s %-8.1f\n", 
               students[i].id, students[i].name, students[i].average);
    }

    // 统计分数分布
    int distribution[5] = {0}; // 0-59, 60-69, 70-79, 80-89, 90-100
    for (int i = 0; i < count; i++) {
        for (int j = 0; j < 3; j++) {
            int score = (int)students[i].scores[j];
            if (score < 60) distribution[0]++;
            else if (score < 70) distribution[1]++;
            else if (score < 80) distribution[2]++;
            else if (score < 90) distribution[3]++;
            else distribution[4]++;
        }
    }

    printf("\n分数分布统计:\n");
    printf("不及格(<60): %d\n", distribution[0]);
    printf("及格(60-69): %d\n", distribution[1]);
    printf("中等(70-79): %d\n", distribution[2]);
    printf("良好(80-89): %d\n", distribution[3]);
    printf("优秀(90-100): %d\n", distribution[4]);
}
```
