## 4 实现一个猜拳小游戏

接下来我们通过一个猜拳小游戏开发来练习仓颉-C跨语言编程。通过C语言生成随机选择，仓颉语言处理用户输入和胜负判定。

打开华为开发者空间云主机中的CodeArts IDE for Cangjie编译器，任意窗口下使用快捷键**ALT+P**新建仓颉工程，名称定义为**demo3**，产物类型选择**executable**。

![31ddc6764b687c9439f9711b3386d9ea.png](https://fileserver.developer.huaweicloud.com/FileServer/getFile/spaceguides/000/fe8/1fa/09329602ec000fe81faac006ed7069fa.20250403023748.87600431484668219441731270657111:50560402032629:2421:D5B5B3CDEB9CFB723B871000A1FD95B426E286E4379FBD8743E7254C85F92F59.png?customIdMd=06dbad840af64e1e987b999341e6712e)

在src目录下创建一个**game.c**文件，将下面示例代码内容复制到 game.c。
```
 #include <stdlib.h>
#include <time.h>

// 生成电脑的随机选择（0=石头，1=剪刀，2=布）
int get_computer_choice() {
    static int initialized = 0;
    if (!initialized) {
        srand(time(NULL)); // 初始化随机种子
        initialized = 1;
    }
    return rand() % 3; // 返回0-2之间的随机整数
}
```

用以下代码替换**main.cj**文件原有代码。
``` 
package demo3
import std.io.*
import std.env.*
import std.convert.*
// 声明C函数
foreign func get_computer_choice() : Int32

main(): Unit {
    print("石头剪刀布游戏")
    print("输入数字选择: 0=石头, 1=剪刀, 2=布")

    while (true) {
        print("\n你的选择(0/1/2, 输入q退出): ")
        let input  = getStdIn().readln()
        if (input == "q") {
            print("游戏结束！\n")
            break
        }
        // 获取玩家输入并转为Int32类型
        let player_choice = Int32.parse(input.getOrThrow())
        if (player_choice < 0 || player_choice > 2) {
            print("输入无效! 请输入0-2或q退出")
            continue
        }
        // 调用C函数获取电脑选择
        let computer_choice = unsafe {get_computer_choice()}
        // 判定胜负
        let result = (player_choice - computer_choice + 3) % 3
        var outcome = ""
        if (result == 0) {
            outcome = "平局！"
        } else if (result == 1) {
            outcome = "你输了！"
        } else {
            outcome = "你赢了！"
        }
        // 显示结果
        print("你：${get_name(player_choice)} | 电脑：${get_name(computer_choice)}")
        print(outcome)
        print("\n-----------------------")
    }
}

// 辅助函数：将数字转换为名称
func get_name(choice: Int32) : String {
    if (choice == 0) {
        return "石头"
    }else if (choice == 1) {
        return "剪刀"
    }else if (choice == 2) {
        return "布"
    }else {
        return "未知"
    }
}
```

右键src目录，选择**在集成终端中打开**进入终端窗口，执行以下命令运行猜拳游戏。
``` 
gcc -fPIC -shared game.c -o libgame.so
cjc -L . -l game main.cj -o game_app
./game_app
```
