### 3.3 哈希冲突及解决方案

**哈希冲突**‌是指在使用哈希函数时，不同的键通过哈希函数计算得到相同的哈希值，导致它们被映射到哈希表的同一位置的现象。

由于哈希表的存储空间是有限的，而可能的输入值是无限的，因此总会存在冲突的可能性‌。

而解决哈希冲突，我们有以下几种方案，首先是链地址法。

**1）链地址法**：通过将哈希到同一位置的元素存储在链表中来处理冲突。‌该方法将散列地址相同的元素链接为同义词子表，各链表头结点组成向量结构，实现高效查找、插入和删除操作。‌‌

链地址法代码演示如下：
```
#include <iostream>
#include <list>
#include <vector>
using namespace std;

class HashTable {
    static const int SIZE = 5;
    vector<list<pair<int, string>>> table;

    int hash(int key) {
        return key % SIZE;
    }

public:
    HashTable() : table(SIZE) {}

    void insert(int key, string value) {
        int index = hash(key);
        cout << "插入 (" << key << ", " << value << ") -> 桶" << index;

        // 检查冲突
        if (!table[index].empty()) {
            cout << " [冲突! 已存在 " << table[index].size() << " 个元素]";
        }

        table[index].push_back({key, value});
        cout << endl;
    }

    void display() {
        cout << "\n哈希表内容 (链地址法):\n";
        for (int i = 0; i < SIZE; i++) {
            cout << "桶" << i << ": ";
            for (auto& item : table[i]) {
                cout << "(" << item.first << ", " << item.second << ") ";
            }
            cout << endl;
        }
    }
};

int main() {
    HashTable ht;
    ht.insert(10, "苹果");
    ht.insert(20, "香蕉");  // 冲突 (10 % 5 = 0, 20 % 5 = 0)
    ht.insert(15, "橙子");  // 冲突 (15 % 5 = 0)
    ht.insert(7, "葡萄");
    ht.insert(12, "柠檬");  // 冲突 (7 % 5 = 2, 12 % 5 = 2)
    ht.display();
    return 0;
}
```

