**2）线性探测法:** **‌**线性探测法是解决哈希表冲突的开放寻址策略‌，其核心机制是通过顺序探测下一个空闲位置实现冲突处理。当哈希冲突发生时，该方法依次检查哈希表中后续槽位（直到表尾后回到表头），直至找到空槽插入数据。该方法的优势在于实现简单，但可能因"堆积现象"降低查询效率。‌‌

线性探测法代码演示如下：
```
#include <iostream>
#include <vector>
using namespace std;

class HashTable {
    static const int SIZE = 7;
    vector<pair<int, string>> table;
    vector<bool> occupied;

    int hash(int key) {
        return key % SIZE;
    }

public:
    HashTable() : table(SIZE, {-1, ""}), occupied(SIZE, false) {}

    void insert(int key, string value) {
        int index = hash(key);
        cout << "插入 (" << key << ", " << value << ") -> 尝试位置: " << index;

        int probes = 0;
        while (occupied[index]) {
            probes++;
            cout << " [冲突! 探测新位置: " << index << "]";
            index = (index + 1) % SIZE;
        }

        table[index] = {key, value};
        occupied[index] = true;
        cout << " -> 最终位置: " << index;
        if (probes > 0) cout << " (探测次数: " << probes << ")";
        cout << endl;
    }

    void display() {
        cout << "\n哈希表内容 (线性探测):\n";
        for (int i = 0; i < SIZE; i++) {
            cout << "位置" << i << ": ";
            occupied[i] ? cout << "(" << table[i].first << ", " << table[i].second << ")" 
                         : cout << "空";
            cout << endl;
        }
    }
};

int main() {
    HashTable ht;
    ht.insert(10, "苹果");
    ht.insert(20, "香蕉");  // 20 % 7 = 6
    ht.insert(15, "橙子");  // 15 % 7 = 1
    ht.insert(8, "葡萄");   // 8 % 7 = 1 -> 冲突
    ht.insert(22, "柠檬");  // 22 % 7 = 1 -> 冲突
    ht.display();
    return 0;
}
```

