## 4 综合案例：学生成绩管理系统

### 4.1 功能需求分析

学生成绩管理系统设计功能如下：

1.  添加学生信息；
2.  查询学生信息；
3.  删除学生信息；
4.  计算平均分；
5.  显示出所有学生；
6.  退出。

### 4.2 代码实现及验证

下面案例使用标准库中unordered_map（哈希表实现）开发的学生成绩管理系统。

代码参考如下：
```
#include <iostream>
#include <unordered_map>
#include <string>
#include <vector>
#include <iomanip>
#include <numeric>

using namespace std;

// 学生结构体
struct Student {
    string name;
    int id;
    double score;
};

// 学生成绩管理系统类
class StudentGradeManager {
private:
    unordered_map<int, Student> studentMap; // 使用哈希表存储学生信息，学号为键

public:
    // 添加学生
    void addStudent(const string& name, int id, double score) {
        if (studentMap.find(id) != studentMap.end()) {
            cout << "学号 " << id << " 已存在！" << endl;
            return;
        }

        Student student;
        student.name = name;
        student.id = id;
        student.score = score;

        studentMap[id] = student;
        cout << "学生 " << name << " 添加成功！" << endl;
    }

    // 查询学生成绩
    void queryStudent(int id) {
        auto it = studentMap.find(id);
        if (it != studentMap.end()) {
            const Student& student = it->second;
            cout << "学号: " << student.id << ", 姓名: " << student.name 
                 << ", 成绩: " << fixed << setprecision(1) << student.score << endl;
        } else {
            cout << "未找到学号为 " << id << " 的学生！" << endl;
        }
    }

    // 删除学生记录
    void deleteStudent(int id) {
        if (studentMap.erase(id) > 0) {
            cout << "学号 " << id << " 的学生记录已删除！" << endl;
        } else {
            cout << "未找到学号为 " << id << " 的学生！" << endl;
        }
    }

    // 计算班级平均分
    void calculateAverage() {
        if (studentMap.empty()) {
            cout << "当前没有学生记录！" << endl;
            return;
        }

        double total = 0.0;
        for (const auto& pair : studentMap) {
            total += pair.second.score;
        }

        double average = total / studentMap.size();
        cout << "班级平均分: " << fixed << setprecision(1) << average << endl;
    }

    // 显示所有学生信息
    void displayAll() {
        if (studentMap.empty()) {
            cout << "当前没有学生记录！" << endl;
            return;
        }

        cout << "所有学生信息:" << endl;
        cout << "学号\t姓名\t成绩" << endl;
        for (const auto& pair : studentMap) {
            const Student& student = pair.second;
            cout << student.id << "\t" << student.name << "\t" 
                 << fixed << setprecision(1) << student.score << endl;
        }
    }

    // 显示菜单
    static void showMenu() {
        cout << "\n学生成绩管理系统" << endl;
        cout << "1. 添加学生" << endl;
        cout << "2. 查询学生" << endl;
        cout << "3. 删除学生" << endl;
        cout << "4. 计算平均分" << endl;
        cout << "5. 显示所有学生" << endl;
        cout << "0. 退出" << endl;
        cout << "请选择操作: ";
    }
};

int main() {
    StudentGradeManager manager;
    int choice;

    do {
        StudentGradeManager::showMenu();
        cin >> choice;

        switch (choice) {
            case 1: {
                string name;
                int id;
                double score;
                cout << "请输入学生姓名: ";
                cin >> name;
                cout << "请输入学号: ";
                cin >> id;
                cout << "请输入成绩: ";
                cin >> score;
                manager.addStudent(name, id, score);
                break;
            }
            case 2: {
                int id;
                cout << "请输入要查询的学号: ";
                cin >> id;
                manager.queryStudent(id);
                break;
            }
            case 3: {
                int id;
                cout << "请输入要删除的学号: ";
                cin >> id;
                manager.deleteStudent(id);
                break;
            }
            case 4:
                manager.calculateAverage();
                break;
            case 5:
                manager.displayAll();
                break;
            case 0:
                cout << "感谢使用，再见！" << endl;
                break;
            default:
                cout << "无效的选择，请重新输入！" << endl;
        }
    } while (choice != 0);

    return 0;
}
```

