## 4. 选择排序
**选择排序**是一种简单直观的排序算法，它的核心思想是重复地在未排序部分中找到最小（或最大）元素，并将其放到已排序部分的末尾。

**具体代码实现：**
Step1：复制以下代码，替换main.cpp文件中的代码。

```
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// 选择排序函数实现
void selectionSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        // 假设当前索引i是最小元素的索引
        int min_index = i;

        // 在未排序部分中查找最小元素
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[min_index]) {
                min_index = j;
            }
        }

        // 将找到的最小元素与当前位置元素交换
        if (min_index != i) {
            int temp = arr[i];
            arr[i] = arr[min_index];
            arr[min_index] = temp;
        }
    }
}

// 打印数组函数
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// 验证数组是否已排序
int isSorted(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        if (arr[i] > arr[i + 1]) {
            return 0; // 未排序
        }
    }
    return 1; // 已排序
}

int main() {
    // 示例1: 整数数组排序
    int numbers[] = {64, 34, 25, 12, 22, 11, 90};
    int n = sizeof(numbers) / sizeof(numbers[0]);
    printf("排序前的数组: \n");
    printArray(numbers, n);
    // 调用选择排序函数
    selectionSort(numbers, n);
    printf("排序后的数组: \n");
    printArray(numbers, n);
    // 验证排序结果
    printf("排序验证: %s\n\n", isSorted(numbers, n) ? "成功" : "失败");
    return 0;
}
```

