**遍历二叉树**：前序遍历、中序遍历、后序遍历、层次遍历。

**前序遍历**：访问顺序为根节点 -\> 左子树 -\> 右子树。

**中序遍历**：访问顺序为左子树 -\> 根节点 -\> 右子树。

**后序遍历**：访问顺序为左子树 -\> 右子树 -\> 根节点。

**层次遍历**：按层次从上到下，从左到右访问节点。

具体代码操作如下：

Step1：复制以下代码，替换main.cpp文件中的代码。
```
#include <stdio.h>
#include <stdlib.h>

typedef struct TreeNode {
    int data;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

// 创建新节点
TreeNode* createNode(int data) {
    TreeNode* newNode = (TreeNode*)malloc(sizeof(TreeNode));
    if (newNode == NULL) {
        printf("内存分配失败\n");
        exit(1);
    }
    newNode->data = data;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// 插入节点（二叉搜索树方式）
TreeNode* insert(TreeNode* root, int data) {
    if (root == NULL) {
        return createNode(data);
    }
    if (data < root->data) {
        root->left = insert(root->left, data);
    } else if (data > root->data) {
        root->right = insert(root->right, data);
    }
    return root;
}

// 前序遍历
void preOrder(TreeNode* root) {
    if (root != NULL) {
        printf("%d ", root->data);
        preOrder(root->left);
        preOrder(root->right);
    }
}

// 中序遍历
void inOrder(TreeNode* root) {
    if (root != NULL) {
        inOrder(root->left);
        printf("%d ", root->data);
        inOrder(root->right);
    }
}

// 后序遍历
void postOrder(TreeNode* root) {
    if (root != NULL) {
        postOrder(root->left);
        postOrder(root->right);
        printf("%d ", root->data);
    }
}

// 层次遍历（使用简单队列实现）
void levelOrder(TreeNode* root) {
    if (root == NULL) return;
    TreeNode* queue[100];  // 简单的队列实现
    int front = 0, rear = 0;
    queue[rear++] = root;
    while (front < rear) {
        TreeNode* current = queue[front++];
        printf("%d ", current->data);

        if (current->left != NULL) {
            queue[rear++] = current->left;
        }
        if (current->right != NULL) {
            queue[rear++] = current->right;
        }
    }
}

int main() {
    TreeNode* root = NULL;
    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 70);
    root = insert(root, 60);
    root = insert(root, 80);

    printf("\n遍历二叉树:\n");
    printf("前序遍历: ");
    preOrder(root);
    printf("\n");
    printf("中序遍历: ");
    inOrder(root);
    printf("\n");
    printf("后序遍历: ");
    postOrder(root);
    printf("\n");
    printf("层次遍历: ");
    levelOrder(root);
    printf("\n");
    return 0;
}
