### 3.2 栈的应用实例

**括号匹配：**检查表达式中的括号是否合法匹配。

**实现思路：**

1.  遇到左括号入栈；
2.  遇到右括号时弹出栈顶元素并检查是否匹配；
3.  最后检查栈是否为空。

具体代码操作如下：

Step1：复制以下代码，替换main.cpp文件中的代码。
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>
#define MAX_SIZE 100

// 栈结构
typedef struct {
    int top;
    int data[MAX_SIZE];
} Stack;
// 初始化栈
void initStack(Stack *s) {
    s->top = -1;
}
// 检查栈是否为空
bool isStackEmpty(Stack *s) {
    return s->top == -1;
}
// 检查栈是否已满
bool isStackFull(Stack *s) {
    return s->top == MAX_SIZE - 1;
}
// 入栈操作
void push(Stack *s, int value) {
    if (isStackFull(s)) {
        printf("栈已满，无法添加元素\n");
        return;
    }
    s->data[++s->top] = value;
}
// 出栈操作
int pop(Stack *s) {
    if (isStackEmpty(s)) {
        printf("栈为空，无法弹出元素\n");
        return -1;
    }
    return s->data[s->top--];
}
// 查看栈顶元素
int peek(Stack *s) {
    if (isStackEmpty(s)) {
        printf("栈为空\n");
        return -1;
    }
    return s->data[s->top];
}
// 打印栈内容
void printStack(Stack *s) {
    if (isStackEmpty(s)) {
        printf("栈为空\n");
        return;
    }
    printf("栈内容 (从顶到底): ");
    for (int i = s->top; i >= 0; i--) {
        printf("%d ", s->data[i]);
    }
    printf("\n");
}

bool isBalancedParentheses(char *expression) {
    Stack s;
    initStack(&s);
    for (int i = 0; expression[i] != '\0'; i++) {
        if (expression[i] == '(' || expression[i] == '[' || expression[i] == '{') {
            push(&s, expression[i]);
        } else if (expression[i] == ')' || expression[i] == ']' || expression[i] == '}') {
            if (isStackEmpty(&s)) {
                return false;
            }
            char topChar = pop(&s);
            if ((expression[i] == ')' && topChar != '(') ||
                (expression[i] == ']' && topChar != '[') ||
                (expression[i] == '}' && topChar != '{')) {
                return false;
            }
        }
    }
    return isStackEmpty(&s);
}

int main() {
    printf("\n=== 栈的应用：括号匹配 ===\n");
    char expr1[] = "({[]})";
    char expr2[] = "({[}])";
    printf("表达式: %s -> %s\n", expr1, isBalancedParentheses(expr1) ? "括号匹配" : "括号不匹配");
    printf("表达式: %s -> %s\n", expr2, isBalancedParentheses(expr2) ? "括号匹配" : "括号不匹配");
    return 0;
}
