### 3.3 队列的基本概念与操作

**先进先出（FIFO）：**最先入队的元素最先出队

**核心操作：**

enqueue()：元素入队；

dequeue()：元素出队；

front()：查看队首元素。

**元素入队**：
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>
#define MAX_SIZE 100
typedef struct {
    int front, rear;
    int data[MAX_SIZE];
} Queue;
// 初始化队列
void initQueue(Queue *q) {
    q->front = -1;
    q->rear = -1;
}
// 检查队列是否为空
bool isQueueEmpty(Queue *q) {
    return q->front == -1;
}
// 检查队列是否已满
bool isQueueFull(Queue *q) {
    return (q->rear + 1) % MAX_SIZE == q->front;
}

// 入队操作
void enqueue(Queue *q, int value) {
    if (isQueueFull(q)) {
        printf("队列已满，无法添加元素\n");
        return;
    }
    if (isQueueEmpty(q)) {
        q->front = 0;
    }
    q->rear = (q->rear + 1) % MAX_SIZE;
    q->data[q->rear] = value;
}
```

**元素出队**：
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <ctype.h>
#define MAX_SIZE 100
typedef struct {
    int front, rear;
    int data[MAX_SIZE];
} Queue;
// 初始化队列
void initQueue(Queue *q) {
    q->front = -1;
    q->rear = -1;
}
// 检查队列是否为空
bool isQueueEmpty(Queue *q) {
    return q->front == -1;
}

// 出队操作
int dequeue(Queue *q) {
    if (isQueueEmpty(q)) {
        printf("队列为空，无法弹出元素\n");
        return -1;
    }
    int value = q->data[q->front];
    if (q->front == q->rear) {
        // 队列只有一个元素
        q->front = q->rear = -1;
    } else {
        q->front = (q->front + 1) % MAX_SIZE;
    }
    return value;
}
