import std.collection.*
// 打印ArrayList函数
func printList(list: ArrayList<Int64>): Unit{
    print("包含元素：")
    for (i in list) {
        print(" ${i}")
    }
    println("\n")
}
main() {
    let list1 = ArrayList<Int64>([0, 1, 2])
    let list2 = list1
    // 修改list2 第一个元素为3
        list2[0] = 3
    // list1，list2第一个元素改为了3
    print("list1 ")
    printList(list1)
    print("list2 ")
    printList(list2)
}
```

