``` language
package org.example.controller;

import ch.qos.logback.core.util.InvocationGate;
import org.example.Entity.Commodity;
import org.example.Entity.Result;
import org.example.service.CommodityService;
import org.example.utils.GsonUtil;
import org.example.utils.JwtUtil;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.cloud.context.config.annotation.RefreshScope;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

/**
 * 商品API
 */
@Validated
@RestController
@RequestMapping("/api/commodity")
@RefreshScope
public class CommodityController {

    @Autowired
    private CommodityService commodityService;

    @Value("${test.price:3}")
    private float price;

    @GetMapping("/list")
    public Result list(@RequestBody String paramStr){
        Map paramMap = GsonUtil.jsonToMap(paramStr);
        //1.分页查询商品列表
        List list = commodityService.list((String) paramMap.get("keyword"), (Integer) paramMap.get("page_number"), (Integer) paramMap.get("page_size"));

        //2.返回结果
        return Result.success(list);
    }

    @GetMapping("/{id}")
    public Result info(@PathVariable("id")Integer id){
        Commodity commodity = commodityService.findCommodityById(id);
        float oldprice = commodity.getPrice();
        commodity.setPrice(price*oldprice);
        return Result.success(commodity);
    }

}

```
